#include <iostream>
#include <vector>
// Version A: range-based for
int total_a(const std::vector<int>& v) { int s = 0; for (int x : v) s += x; return s; }
// Version B: index with at()
int total_b(const std::vector<int>& v) { int s = 0; for (std::size_t i = 0; i < v.size(); ++i) s += v.at(i); return s; }
int main() { std::vector<int> v{1,2,3}; std::cout << total_a(v) << ' ' << total_b(v) << '\n'; return 0; }

